/**
 * Finds "carried from last month" Sheet lines (note "__carry__", label "OCT · <spend label>") whose SOURCE
 * Spend no longer exists in the previous month — e.g. after a spend was deleted straight from the DB
 * (the UI's delete never touches the next month's carry line either: it is only regenerated by the Sheet's
 * "refresh carry estimate", rebuild, or wind-down). Also prints the earlier month's status and its settlement
 * payments, because deleting a spend changes that month's settlement net.
 *
 * Dry run:  node_modules/.bin/tsx scripts/audit-orphan-carry.ts
 * Apply:    node_modules/.bin/tsx scripts/audit-orphan-carry.ts --apply   (deletes ONLY the orphan carry lines)
 */
import { config } from "dotenv";
import { resolve } from "node:path";
config({ path: resolve(__dirname, "..", ".env.local") });
config({ path: resolve(__dirname, "..", ".env") });
const url = process.env.DATABASE_URL ?? "";
if (!url || !/^postgres/i.test(url)) { console.error("✗ DATABASE_URL missing. Run: vercel env pull .env.local"); process.exit(1); }
const APPLY = process.argv.includes("--apply");
const inr = (n: number) => "₹" + Math.round(n).toLocaleString("en-IN");

async function main() {
  const { PrismaClient } = await import("@prisma/client");
  const { PrismaPg } = await import("@prisma/adapter-pg");
  const prisma = new PrismaClient({ adapter: new PrismaPg({ connectionString: url }) });
  try {
    const carries = await prisma.expenseEntry.findMany({
      where: { note: "__carry__" },
      include: { period: true, category: { select: { name: true } }, member: { select: { name: true } } },
      orderBy: [{ periodId: "asc" }, { id: "asc" }],
    });
    const orphans: typeof carries = [];
    for (const c of carries) {
      const py = c.period.month === 1 ? c.period.year - 1 : c.period.year;
      const pm = c.period.month === 1 ? 12 : c.period.month - 1;
      const prev = await prisma.period.findUnique({ where: { householdId_year_month: { householdId: c.period.householdId, year: py, month: pm } } });
      if (!prev) continue;
      const rest = c.label.replace(/^[^·]*·\s*/, "");
      const src = await prisma.spend.findFirst({ where: { periodId: prev.id, categoryId: c.categoryId, label: rest, memberId: c.memberId } });
      if (src && Math.abs(src.amount - c.amount) < 0.005) continue;
      orphans.push(c);
      const settles = await prisma.settlementRecord.findMany({ where: { periodId: prev.id }, select: { fromMemberId: true, toMemberId: true, amount: true } });
      console.log(`ORPHAN #${c.id} "${c.label}" ${inr(c.amount)} · ${c.category.name} · ${c.member?.name ?? "—"} · in ${c.period.label}[${c.period.status}]`);
      console.log(`   source month ${prev.label} is ${prev.status}; settlement payments recorded there: ${settles.length ? settles.map((s) => `${s.fromMemberId}→${s.toMemberId} ${inr(s.amount)}`).join(", ") : "none"}`);
    }
    if (!orphans.length) { console.log("No orphan carry lines."); return; }
    if (!APPLY) { console.log(`\n(dry run) ${orphans.length} orphan line(s). Re-run with --apply to delete them.\n`); return; }
    const r = await prisma.expenseEntry.deleteMany({ where: { id: { in: orphans.map((o) => o.id) }, note: "__carry__" } });
    console.log(`\n✓ Deleted ${r.count} orphan carry line(s). Tap "Refresh data" in the app to bust the cache.\n`);
  } finally {
    await prisma.$disconnect();
  }
}
main().catch((e) => { console.error(e); process.exit(1); });
